//! Frames and messages of protocol 1, as `Framing` and `IpcMessage` of `Sermofur.Daemon`.
//!
//! A frame is a little-endian `u32` with the size of the body, then a UTF-8 JSON body without
//! BOM. The body is one flat object; null fields are not written, and strings are escaped as
//! `JavaScriptEncoder.UnsafeRelaxedJsonEscaping` does (table generated by
//! `rust/tools/framing-oracle`). A body is read with the rules of `System.Text.Json`
//! (`sermofur_core::stj`): any syntax or conversion error is `protocol_error`,
//! « Malformed message. ». The golden table is `rust/tests/golden/framing.json`.

use std::fmt::Write as _;
use std::io::{self, Read, Write};

use sermofur_core::error::SermofurError;
use sermofur_core::stj::{self, Node};

use crate::relaxed_escape_table::UNICODE_ESCAPED_RANGES;

/// Largest request the daemon accepts (256 KiB).
pub const MAX_BODY_BYTES: usize = 256 * 1024;

/// Largest answer a client accepts (16 MiB).
pub const MAX_RESPONSE_BYTES: usize = 16 * 1024 * 1024;

/// Version of the protocol spoken by this build.
pub const CURRENT_PROTOCOL: i32 = 1;

/// Kinds of message of protocol 1 (`MessageKind`).
pub mod kind {
    pub const HELLO: &str = "hello";
    pub const WELCOME: &str = "welcome";
    pub const RUN: &str = "run";
    pub const RESULT: &str = "result";
    pub const NOT_SERVING: &str = "not_serving";
    pub const STATUS: &str = "status";
    pub const SHUTDOWN: &str = "shutdown";
    pub const STOPPING: &str = "stopping";
    pub const ERROR: &str = "error";
}

/// One message of the local protocol: `kind` says which fields are meaningful.
///
/// An `argv` item may be `None`: the .NET reader accepts `null` inside the array, and writes it
/// back as `null`.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct IpcMessage {
    pub kind: String,
    pub protocol: Option<i32>,
    pub tool_version: Option<String>,
    pub cwd: Option<String>,
    pub pid: Option<i32>,
    pub id: Option<i64>,
    pub argv: Option<Vec<Option<String>>>,
    pub exit_code: Option<i32>,
    pub stdout: Option<String>,
    pub stderr: Option<String>,
    pub code: Option<String>,
    pub message: Option<String>,
    pub started_at: Option<String>,
    pub instances_open: Option<i32>,
    pub clients: Option<i32>,
    /// Registry file the daemon reads (status only).
    pub registry: Option<String>,
}

impl IpcMessage {
    /// A message of the given kind and no other field.
    pub fn new(kind: &str) -> Self {
        Self {
            kind: kind.to_owned(),
            ..Self::default()
        }
    }

    /// `IpcMessage.Failure`: an `error` message with a code, a text and maybe the request id.
    pub fn failure(code: &str, message: &str, id: Option<i64>) -> Self {
        Self {
            code: Some(code.to_owned()),
            message: Some(message.to_owned()),
            id,
            ..Self::new(kind::ERROR)
        }
    }
}

/// Why a frame could not be read or written: a refusal of the protocol, or a failure of the
/// stream itself (the .NET code lets the `IOException` through).
#[derive(Debug)]
pub enum FrameError {
    Refused(SermofurError),
    Io(io::Error),
}

impl From<SermofurError> for FrameError {
    fn from(error: SermofurError) -> Self {
        Self::Refused(error)
    }
}

impl From<io::Error> for FrameError {
    fn from(error: io::Error) -> Self {
        Self::Io(error)
    }
}

fn protocol_error(message: &str) -> SermofurError {
    SermofurError::new("protocol_error", message, 3)
}

/// Reads one message of at most `limit` bytes, or `None` when the stream ends cleanly between
/// two frames. A frame over the limit is refused from its header, before its body is read.
pub fn read(stream: &mut impl Read, limit: usize) -> Result<Option<IpcMessage>, FrameError> {
    let mut header = [0u8; 4];
    let got = fill(stream, &mut header)?;
    if got == 0 {
        return Ok(None);
    }
    if got < header.len() {
        return Err(protocol_error("Truncated frame header.").into());
    }
    let length = u32::from_le_bytes(header);
    if length == 0 {
        return Err(protocol_error("Empty frame.").into());
    }
    // A length that does not fit in usize is over any limit.
    let size = usize::try_from(length).unwrap_or(usize::MAX);
    if size > limit {
        return Err(SermofurError::new(
            "request_too_large",
            format!("Frame of {length} bytes; the limit is {limit}."),
            1,
        )
        .into());
    }
    let mut body = vec![0u8; size];
    if fill(stream, &mut body)? < size {
        return Err(protocol_error("Truncated frame body.").into());
    }
    Ok(Some(decode(&body)?))
}

/// Writes one message of at most `limit` bytes as a single frame, and flushes it.
pub fn write(
    stream: &mut impl Write,
    message: &IpcMessage,
    limit: usize,
) -> Result<(), FrameError> {
    let frame = encode(message, limit)?;
    stream.write_all(&frame)?;
    stream.flush()?;
    Ok(())
}

/// Header and body of a message; a body over `limit` is `request_too_large`.
pub fn encode(message: &IpcMessage, limit: usize) -> Result<Vec<u8>, SermofurError> {
    let body = body(message);
    let refused = || {
        SermofurError::new(
            "request_too_large",
            format!("Message of {} bytes; the limit is {limit}.", body.len()),
            1,
        )
    };
    if body.len() > limit {
        return Err(refused());
    }
    // A body over 4 GiB cannot be framed whatever the limit of the caller.
    let length = u32::try_from(body.len()).map_err(|_| refused())?;
    let mut frame = Vec::with_capacity(body.len() + 4);
    frame.extend_from_slice(&length.to_le_bytes());
    frame.extend_from_slice(body.as_bytes());
    Ok(frame)
}

/// The message of a frame body: malformed UTF-8 or JSON, or no kind, is `protocol_error`.
pub fn decode(body: &[u8]) -> Result<IpcMessage, SermofurError> {
    // Strict decoding first: invalid UTF-8 is never repaired into a valid request.
    let json = std::str::from_utf8(body).map_err(|_| malformed())?;
    let node = stj::parse(json).map_err(|_| malformed())?;
    let Some(properties) = stj::object(&node).map_err(|_| malformed())? else {
        // A `null` document: the .NET serializer returns no message.
        return Err(protocol_error("Message without kind."));
    };
    let mut message = IpcMessage::default();
    // `Kind` is a `required` property: a missing one is a JSON error, a null one is not.
    let mut kind: Option<Option<String>> = None;
    // Properties in order, the last one wins; an unknown one is skipped.
    for (name, value) in properties {
        let converted = match name {
            "kind" => text(value).map(|v| kind = Some(v)),
            "protocol" => int(value).map(|v| message.protocol = v),
            "toolVersion" => text(value).map(|v| message.tool_version = v),
            "cwd" => text(value).map(|v| message.cwd = v),
            "pid" => int(value).map(|v| message.pid = v),
            "id" => int(value).map(|v| message.id = v),
            "argv" => argv(value).map(|v| message.argv = v),
            "exitCode" => int(value).map(|v| message.exit_code = v),
            "stdout" => text(value).map(|v| message.stdout = v),
            "stderr" => text(value).map(|v| message.stderr = v),
            "code" => text(value).map(|v| message.code = v),
            "message" => text(value).map(|v| message.message = v),
            "startedAt" => text(value).map(|v| message.started_at = v),
            "instancesOpen" => int(value).map(|v| message.instances_open = v),
            "clients" => int(value).map(|v| message.clients = v),
            "registry" => text(value).map(|v| message.registry = v),
            _ => Some(()),
        };
        converted.ok_or_else(malformed)?;
    }
    match kind {
        None => Err(malformed()),
        Some(None) => Err(protocol_error("Message without kind.")),
        Some(Some(k)) if k.is_empty() => Err(protocol_error("Message without kind.")),
        Some(Some(k)) => {
            message.kind = k;
            Ok(message)
        }
    }
}

fn malformed() -> SermofurError {
    protocol_error("Malformed message.")
}

fn text(node: &Node) -> Option<Option<String>> {
    stj::text(node).ok()
}

fn int<T: std::str::FromStr>(node: &Node) -> Option<Option<T>> {
    match node {
        Node::Null => Some(None),
        _ => stj::integer(node).ok().map(Some),
    }
}

fn argv(node: &Node) -> Option<Option<Vec<Option<String>>>> {
    match node {
        Node::Null => Some(None),
        Node::Array(items) => items.iter().map(text).collect::<Option<Vec<_>>>().map(Some),
        _ => None,
    }
}

/// Reads until `buffer` is full or the stream ends; returns the number of bytes read.
fn fill(stream: &mut impl Read, buffer: &mut [u8]) -> io::Result<usize> {
    let mut total = 0;
    while total < buffer.len() {
        match stream.read(&mut buffer[total..]) {
            Ok(0) => break,
            Ok(read) => total += read,
            Err(error) if error.kind() == io::ErrorKind::Interrupted => {}
            Err(error) => return Err(error),
        }
    }
    Ok(total)
}

/// The JSON body, fields in the order of the .NET record, null fields left out.
fn body(m: &IpcMessage) -> String {
    let mut out = String::from("{");
    string_field(&mut out, "kind", Some(&m.kind));
    int_field(&mut out, "protocol", m.protocol.map(i64::from));
    string_field(&mut out, "toolVersion", m.tool_version.as_deref());
    string_field(&mut out, "cwd", m.cwd.as_deref());
    int_field(&mut out, "pid", m.pid.map(i64::from));
    int_field(&mut out, "id", m.id);
    if let Some(argv) = &m.argv {
        out.push_str(",\"argv\":[");
        for (i, item) in argv.iter().enumerate() {
            if i > 0 {
                out.push(',');
            }
            match item {
                Some(text) => push_string(&mut out, text),
                None => out.push_str("null"),
            }
        }
        out.push(']');
    }
    int_field(&mut out, "exitCode", m.exit_code.map(i64::from));
    string_field(&mut out, "stdout", m.stdout.as_deref());
    string_field(&mut out, "stderr", m.stderr.as_deref());
    string_field(&mut out, "code", m.code.as_deref());
    string_field(&mut out, "message", m.message.as_deref());
    string_field(&mut out, "startedAt", m.started_at.as_deref());
    int_field(&mut out, "instancesOpen", m.instances_open.map(i64::from));
    int_field(&mut out, "clients", m.clients.map(i64::from));
    string_field(&mut out, "registry", m.registry.as_deref());
    out.push('}');
    out
}

/// Writes `"name":` after a comma unless it is the first field.
fn name(out: &mut String, name: &str) {
    if out.len() > 1 {
        out.push(',');
    }
    out.push('"');
    out.push_str(name);
    out.push_str("\":");
}

fn string_field(out: &mut String, field: &str, value: Option<&str>) {
    if let Some(value) = value {
        name(out, field);
        push_string(out, value);
    }
}

fn int_field(out: &mut String, field: &str, value: Option<i64>) {
    if let Some(value) = value {
        name(out, field);
        let _ = write!(out, "{value}");
    }
}

/// A JSON string with the escaping of `UnsafeRelaxedJsonEscaping`.
fn push_string(out: &mut String, text: &str) {
    out.push('"');
    for c in text.chars() {
        let scalar = u32::from(c);
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\u{8}' => out.push_str("\\b"),
            '\t' => out.push_str("\\t"),
            '\n' => out.push_str("\\n"),
            '\u{c}' => out.push_str("\\f"),
            '\r' => out.push_str("\\r"),
            _ if scalar > 0xFFFF => {
                // Above the Basic Multilingual Plane: a surrogate pair, one `\uXXXX` per unit.
                let mut units = [0u16; 2];
                for unit in c.encode_utf16(&mut units) {
                    let _ = write!(out, "\\u{unit:04X}");
                }
            }
            _ if is_escaped(scalar) => {
                let _ = write!(out, "\\u{scalar:04X}");
            }
            _ => out.push(c),
        }
    }
    out.push('"');
}

fn is_escaped(scalar: u32) -> bool {
    UNICODE_ESCAPED_RANGES
        .binary_search_by(|&(start, end)| {
            if end < scalar {
                std::cmp::Ordering::Less
            } else if start > scalar {
                std::cmp::Ordering::Greater
            } else {
                std::cmp::Ordering::Equal
            }
        })
        .is_ok()
}
